import React from "react";
import { Container, Row, Col } from "react-bootstrap";
import Navigation from "../components/Navigation";
import Footer from "../components/Footer";

const styles = {
  page: {
    backgroundColor: "#2d2d2d",
    minHeight: "100vh",
    display: "flex",
    flexDirection: "column",
  },
  container: {
    color: "white",
    padding: "5rem 0",
  },
  heroText: {
    fontSize: "3rem",
    fontWeight: "bold",
  },
  leadText: {
    fontSize: "1.2rem",
    marginTop: "1rem",
  },
  storeBadges: {
    marginTop: "1rem",
    display: "flex",
    alignItems: "center",
  },
  playBadge: {
    width: "150px",
    marginRight: "10px",
  },
  appStoreBadge: {
    width: "40px",
    background: "#fff",
    borderRadius: "8px",
    padding: "4px",
  },
  videoContainer: {
    width: "100%",
    display: "flex",
    justifyContent: "center",
    alignItems: "flex-end", // Align video exactly to the bottom
    overflow: "hidden",
    paddingBottom: "0px",
  },
  video: {
    width: "100%",
    height: "auto", // Maintain aspect ratio
    maxHeight: "500px",
    objectFit: "cover", // Ensures it fills the space properly
    borderRadius: "12px",
    marginBottom: "-3px", // Adjust this value if needed
  },
  whiteSection: {
    backgroundColor: "#fff",
    color: "#000",
    padding: "5rem 0",
    textAlign: "center",
  },
  rewardsSection: {
    backgroundColor: "#f9f9f9",
    color: "#000",
    padding: "5rem 0",
    textAlign: "center",
  },
};

const Home = () => {
  return (
    <div style={styles.page}>
      {/* Navbar */}
      <Navigation />

      {/* Hero Section */}
      <Container style={styles.container}>
        <Row className="align-items-center">
          {/* Left Column: Text */}
          <Col md={6}>
            <h1 style={styles.heroText}>For all things money</h1>
            <p style={styles.leadText}>
              Whether it's planning your savings with a new-age savings account,
              investing in mutual funds and high-interest products, or tracking
              your expenses — do it all on Fi.
            </p>

            {/* Store Badges */}
            <div style={styles.storeBadges}>
              <a href="#!">
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/7/78/Google_Play_Store_badge_EN.svg"
                  alt="Get it on Google Play"
                  style={styles.playBadge}
                />
              </a>
              <a href="#!">
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/a/ab/Apple-logo.png"
                  alt="Download on the App Store"
                  style={styles.appStoreBadge}
                />
              </a>
            </div>
          </Col>

          {/* Right Column: Video */}
          <Col md={6} style={styles.videoContainer}>
            <video style={styles.video} autoPlay loop muted playsInline>
              <source
                src="https://dza2kd7rioahk.cloudfront.net/assets/videos/home-page_poster.webm"
                type="video/webm"
              />
              Your browser does not support the video tag.
            </video>
          </Col>
        </Row>
      </Container>

      {/* Savings Account Section */}
      <section style={styles.whiteSection}>
        <Container>
          <h2>Get a savings account unlike any other</h2>
          <img
            src="https://dza2kd7rioahk.cloudfront.net/assets/svgs/debit-card-home.svg"
            alt="Debit Card"
            className="img-fluid mb-4"
            style={{ maxWidth: "400px" }}
          />
          <ul className="list-unstyled d-inline-block text-start">
            <li>No minimum balance on select plans ✌️</li>
            <li>Zero Forex on Select Plans✨</li>
            <li>Withdraw from any ATM 🕺</li>
            <li>No hidden fees</li>
            <li>Money insured up to ₹5 lakh ✅</li>
          </ul>
        </Container>
      </section>

      {/* Rewards Section */}
      <section style={styles.rewardsSection}>
        <Container>
          <h2>You earn rewards for saving, imagine!</h2>
          <p style={{ maxWidth: "600px", margin: "auto" }}>
            It’s about time, right? Rewards are a way of recognizing good
            financial habits. With goodies not just when you shop, but even when
            you save.
          </p>
          <video style={styles.video} autoPlay loop muted playsInline>
            <source
              src="https://dza2kd7rioahk.cloudfront.net/assets/videos/home-page_rewards-section.mp4"
              type="video/mp4"
            />
            Your browser does not support the video tag.
          </video>
        </Container>
      </section>

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default Home;
